mapper.select:
SELECT bp.brd_pst_uuid AS uuid, bc.nm AS ctgr_nm, bp.ttl, bp.view_cnt, mp.nick_nm AS athr_nick_nm,
bp.created_at FROM tb_brd_pst bp LEFT JOIN tb_brd_ctgr bc ON bc.brd_ctgr_idx = bp.brd_ctgr_idx LEFT JOIN tb_mbr_prfl mp ON mp.mbr_acct_idx = bp.mbr_acct_idx
ORDER BY ${req.orderByClause}, bp.brd_pst_idx DESC LIMIT #{req.size} OFFSET #{req.offset}

SELECT EXISTS(
    SELECT 1
    FROM tb_brd_ctgr
    WHERE nm = #{name}

        AND brd_ctgr_uuid != CAST(#{excludeUuid} AS UUID)

)

